    "ntById('ipCard').style.display = 'none';\ndocument.getElementById('btnGoDashboard').style.display = "
    "'none';\ndocument.getElementById('btnCloseModal').style.display = 'none';\n}\nfunction closeModal() "
    "{\ndocument.getElementById('modalOverlay').style.display = 'none';\n}\nfunction toggleAdvanced() {\n"
    "const box = document.getElementById('advBox');\nconst arrow = document.getElementById('advArrow');\n"
    "if (box.style.display === 'block') {\nbox.style.display = 'none';\narrow.innerText = '▼';\n} else {\n"
    "box.style.display = 'block';\narrow.innerText = '▲';\n}\n}\nfunction togglePwdVisibility() {\nconst "
    "input = document.getElementById('wifiPwd');\ninput.type = (input.type === 'password') ? 'text' : 'pa"
    "ssword';\n}\n</script>\n</body>\n</html>";

